                    if v == 0 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
                    elif v == bg_color:
                        reachable_bg = True
                    elif v == special_val:
                        reachable_special = True

        return reachable_bg and reachable_special

    return bfs_from(start_r, start_c)

