from collections import deque

def flood_fill_from_sources(grid, source_values):
    """Flood fill through 0s starting from cells with source values"""
    h, w = len(grid), len(grid[0])
    visited = set()

    # Find all source cells and do BFS
    queue = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] in source_values:
                queue.append((r, c))
                visited.add((r, c))

    while queue:
        r, c = queue.pop(0)
        val = grid[r][c]

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                neighbor_val = grid[nr][nc]
                if neighbor_val == 0:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
                elif neighbor_val not in source_values and neighbor_val != 0:
                    # Hit a barrier
                    pass

    return visited

